import{_ as r}from"./chunks/14.D9M16Vmq.js";import{_ as s}from"./chunks/image1.YJCAcCic.js";import{_ as l,a as c}from"./chunks/image.DUp49IjQ.js";import{_ as g,a as o,b as d,c as h}from"./chunks/image4.FCpLmD95.js";import{_ as m}from"./chunks/image14.CLKeYbCZ.js";import{_ as a}from"./chunks/image.BikqRkQy.js";import{_ as p}from"./chunks/image15.tCW31st1.js";import{_ as u,a as e,b as f,c as y}from"./chunks/community.D8XXOc5B.js";import{_}from"./chunks/image3.BGENV5O0.js";import{_ as b}from"./chunks/image6.Cdq5CsCC.js";import{_ as v,C as w,o as x,c as k,ak as i,E as z}from"./chunks/framework.Db7dlGMu.js";const S="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1._FTXGqPG.png",T="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image100.DjiLoPBt.png",P="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.B-KWDt-4.png",A="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image5.BVLhfKBK.png",C="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.HuuYWeFV.png",M=JSON.parse('{"title":"3.14 Avoidance Flyer","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.14 Avoidance Flyer.md","filePath":"docs/3. Creative Building & Styling/3.14 Avoidance Flyer.md"}'),q={name:"docs/3. Creative Building & Styling/3.14 Avoidance Flyer.md"};function D(I,t,W,E,L,B){const n=w("pdf");return x(),k("div",null,[t[0]||(t[0]=i('<h1 id="_3-14-avoidance-flyer" tabindex="-1">3.14 Avoidance Flyer <a class="header-anchor" href="#_3-14-avoidance-flyer" aria-label="Permalink to &quot;3.14 Avoidance Flyer&quot;">​</a></h1><h2 id="_3-14-1-lesson-introduction" tabindex="-1">3.14.1 Lesson Introduction <a class="header-anchor" href="#_3-14-1-lesson-introduction" aria-label="Permalink to &quot;3.14.1 Lesson Introduction&quot;">​</a></h2><p>The Avoidance Flyer is an engaging robotic building block model designed for interactive aerial simulation. The front of the fuselage incorporates the WonderLens vision module as its visual camera, while a 360° block motor governs lateral obstacle avoidance translation and a 270° block servo controls altitude elevation and descent. The modular mechanical design ensures straightforward assembly and accessible wiring. The camera recognizes different tag IDs to execute corresponding flight maneuvers: tag 1 triggers takeoff elevation, tag 2 initiates landing homing, and tag 3 commands lateral avoidance based on detected position, shifting right when the tag appears on the left. This project provides hands-on exploration of AI tag recognition and multi-servo motion linkage.</p><img loading="lazy" height="1080" width="1080" src="'+r+'" class="common_img" style="width:300px;aspect-ratio:1080 / 1080;"><h2 id="_3-14-2-learning-objectives" tabindex="-1">3.14.2 Learning Objectives <a class="header-anchor" href="#_3-14-2-learning-objectives" aria-label="Permalink to &quot;3.14.2 Learning Objectives&quot;">​</a></h2><ol><li>Master data acquisition and function programming for tag recognition using the WonderLens vision module, including reading tag IDs and detecting tag orientations.</li><li>Program speed control routines for the 360° block motor and precision angle positioning routines for the 270° block servo to execute takeoff, landing, and lateral avoidance maneuvers.</li><li>Complete system linkage debugging across tag recognition and dual-servo motions to achieve synchronized flight responses to detected tag commands.</li><li>Assemble the complete flyer model and debug the interaction program. Develop foundational skills in building robotic projects combining diverse servos with AI vision command interactions.</li></ol><h2 id="_3-14-3-assembly-guide" tabindex="-1">3.14.3 Assembly Guide <a class="header-anchor" href="#_3-14-3-assembly-guide" aria-label="Permalink to &quot;3.14.3 Assembly Guide&quot;">​</a></h2>',7)),z(n,{src:"../../_static/shared/pdf/chapter_3/14.pdf"}),t[1]||(t[1]=i('<h2 id="_3-14-4-hardware-wiring" tabindex="-1">3.14.4 Hardware Wiring <a class="header-anchor" href="#_3-14-4-hardware-wiring" aria-label="Permalink to &quot;3.14.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to port <strong>P1</strong> of the ESP32 controller.</p><p>Connect the 270° block servo cable to port <strong>S1</strong> of the ESP32 controller, ensuring the <strong>orange</strong> wire is plugged into the <strong>white</strong> pin of S1.</p><p>Connect the 360° block motor cable to port <strong>S2</strong> of the ESP32 controller, ensuring the <strong>orange</strong> wire is plugged into the <strong>white</strong> pin of S2.</p><p>Wiring diagram:</p><img loading="lazy" height="1220" width="1120" src="'+S+'" class="common_img" style="width:400px;aspect-ratio:1120 / 1220;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When using the 270° block servo for the first time, detach the gear and its attached building block components from the servo before uploading the program. Upload the lesson program to the ESP32 controller and wait for the servo to rotate to its initial home position, 135°. Once initialized, reattach the components. This step can be skipped if a servo homing routine has already been executed.</strong></p></div><img loading="lazy" height="1080" width="1080" src="'+T+'" class="common_img" style="width:300px;aspect-ratio:1080 / 1080;"><h2 id="_3-14-5-programming" tabindex="-1">3.14.5 Programming <a class="header-anchor" href="#_3-14-5-programming" aria-label="Permalink to &quot;3.14.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1)  Program Schematic&quot;">​</a></h3><img loading="lazy" height="560" width="370" src="'+P+'" class="common_img" style="width:350px;aspect-ratio:370 / 560;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:408 / 303;" height="303" width="408" src="'+l+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:73 / 53;" height="53" width="73" src="'+c+'" class="common_img"></td><td style="text-align:left;">Compares the left value with a specified value and returns a boolean greater-than result.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:173 / 41;" height="41" width="173" src="'+g+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:73 / 53;" height="53" width="73" src="'+o+'" class="common_img"></td><td style="text-align:left;">Creates a custom variable to store data.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:312 / 115;" height="115" width="312" src="'+d+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:73 / 53;" height="53" width="73" src="'+o+'" class="common_img"></td><td style="text-align:left;">Reads data stored in the specified variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:522 / 138;" height="138" width="522" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:73 / 53;" height="53" width="73" src="'+o+'" class="common_img"></td><td style="text-align:left;">Assigns a specified value to the custom variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:524 / 108;" height="108" width="524" src="'+m+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:75 / 51;" height="51" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Controls the servo connected to the specified port to rotate at the set speed.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:929 / 103;" height="103" width="929" src="'+p+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:75 / 51;" height="51" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Controls the angle servo to rotate to a target angle within the specified time and configures delay mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:760 / 412;" height="412" width="760" src="'+u+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+e+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:432 / 117;" height="117" width="432" src="'+f+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+e+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera frame and acquires recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:749 / 97;" height="97" width="749" src="'+_+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+e+'" class="common_img"></td><td style="text-align:left;">Determines whether a specified tag ID is recognized in the frame and returns a boolean result.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:990 / 358;" height="358" width="990" src="'+A+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+e+'" class="common_img"></td><td style="text-align:left;">Reads coordinates, size, 3-axis translation, and rotation data for the specified tag ID.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong>, switch its operating mode to tag recognition, and initialize the variable <code>Angle</code> to 135. Configure the 270° block servo <strong>S1</strong> to rotate to <code>Angle</code> over 1,000 ms, set the speed of servo <strong>S2</strong> to 0, and pause for 2 s.</p></li><li><p>Main Loop: The program executes continuously. Update and retrieve recognition results from the WonderLens vision module. When tag ID 1 is recognized, configure servo <strong>S2</strong> to rotate at a speed of 80. When tag ID 2 is recognized, reset <code>Angle</code> to 135, command servo <strong>S1</strong> to rotate to <code>Angle</code>, pause for 1 s, and stop servo <strong>S2</strong>. When tag ID 3 is recognized, store the horizontal X-coordinate of the tag center in the variable <code>Location</code>. When <code>Location</code> exceeds 150, set <code>Angle</code> to 155. Otherwise, set <code>Angle</code> to 115. Command servo <strong>S1</strong> to rotate to the updated angle and pause for 1 s. Each loop cycle pauses for 0.1 s.</p></li></ol><img loading="lazy" height="1075" width="704" src="'+C+'" class="common_img" style="width:500px;aspect-ratio:704 / 1075;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-14-6-program-upload" tabindex="-1">3.14.6 Program Upload <a class="header-anchor" href="#_3-14-6-program-upload" aria-label="Permalink to &quot;3.14.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+b+'" class="common_img" style="width:800px;aspect-ratio:640 / 360;"><h2 id="_3-14-7-expansion-and-challenge" tabindex="-1">3.14.7 Expansion and Challenge <a class="header-anchor" href="#_3-14-7-expansion-and-challenge" aria-label="Permalink to &quot;3.14.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: RGB Lighting Interaction Upgrades with Tag Linkage</strong></p><ol><li><p>Project Goal: Retain the foundational maneuvers of tag 1 takeoff, tag 2 landing, and tag 3 lateral avoidance while introducing synchronized RGB lighting effects. Tag 1 triggers a rainbow gradient cycle. Tag 2 turns off the lighting. Tag 3 displays a red gradient for left offsets and a blue gradient for right offsets, enriching interactive feedback.</p></li><li><p>Implementation Strategy: Add RGB lighting control blocks within the existing multi-tag conditional branches. Preserve the elevation and lateral translation routines for tags 1, 2, and 3 while binding each branch to a dedicated lighting pattern, enabling synchronized flight and lighting transitions without mutual interference.</p></li><li><p>Key Challenges: Ensuring stable multi-tag discrimination without false triggers, preventing lighting cycles from blocking servo routines, and achieving smooth, synchronized transitions between servo motions and lighting states.</p></li></ol><p><strong>Challenge Task 2: Delayed Automatic Landing and Homing Without Tags</strong></p><ol><li><p>Project Goal: When no tags appear in the camera view for 5 s continuously, the model automatically executes a landing routine. The 270° block servo returns to the 135° home position, all RGB lights extinguish, and the system enters an idle standby state.</p></li><li><p>Implementation Strategy: Introduce a timer variable to start a countdown whenever no tag is detected. If a tag is detected during the countdown, corresponding flight routines resume. When the countdown reaches zero, execute the landing homing routine and turn off the lighting.</p></li><li><p>Key Challenges: Ensuring timer execution does not delay continuous tag recognition, and maintaining precise angle positioning when the 270° block servo homes to 135°.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Tag Recognition</strong></p><ol><li><p>Tag-Controlled Elevation Display Stand: Retain the tag recognition routines and use dual servos to elevate and translate exhibits horizontally, switching display poses based on different tags.</p></li><li><p>Multi-Mode Lighting Controller: Remove the servo mechanism and switch static, gradient, or flashing RGB effects solely by recognizing designated tag IDs.</p></li><li><p>Universal Adaptation Strategy: Keep the low-level camera tag recognition routines unchanged, and modify only the servo logic or swap output peripherals. Based on the logic of executing dedicated actions upon recognizing specific tag IDs, diverse multi-command robotic projects can be developed.</p></li></ol><h2 id="_3-14-8-q-a" tabindex="-1">3.14.8 Q&amp;A <a class="header-anchor" href="#_3-14-8-q-a" aria-label="Permalink to &quot;3.14.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: During servo wiring, the orange signal wire must connect to the white pin of the corresponding servo port. What problems occur if it is wired incorrectly?</strong></p><p><strong>Answer</strong>: The white pin of ports <strong>S1</strong> and <strong>S2</strong> is dedicated to transmitting control signals, which the 360° block motor and 270° block servos rely on to regulate fuselage translation and elevation angles. If the orange signal wire connects to power or ground pins, the controller cannot transmit control commands. Two primary failures occur. First, the affected servo remains completely motionless, preventing the aircraft from taking off, landing, or performing lateral avoidance. Second, the servo vibrates erratically and rotates uncontrollably, which can cause overheating and hardware damage. In addition, all program code for takeoff, landing, avoidance maneuvers, and 270° servo homing to 135° becomes ineffective, preventing command-guided flight operations.</p><p><strong>Question 2: The vision module recognizes tags normally, but the aircraft does not elevate or translate at all. What are the most common causes and troubleshooting steps?</strong></p><p><strong>Answer</strong>: 1. Wiring Fault: The orange signal wires of the 360° block motor and 270° block servos are not connected to the white signal pins of ports <strong>S1</strong> and <strong>S2</strong>. Troubleshooting: Disconnect the power, then verify the three-pin sequence of both servos against the wiring diagram.</p><ol start="2"><li><p>Program Fault: The servo control blocks are placed outside the conditional branches for tag recognition, or the 270° servo homing routine was omitted before assembly. Troubleshooting: Complete the servo homing routine first, then place the takeoff, landing, and lateral translation commands inside their corresponding tag recognition branches.</p></li><li><p>Hardware Damage: One or both servos are defective, or ports <strong>S1</strong> and <strong>S2</strong> on the ESP32 controller are damaged. Troubleshooting: Connect known functional servos to ports <strong>S1</strong> and <strong>S2</strong> for testing. If they still fail to rotate, test the servos on alternative servo ports on the controller to isolate the issue.</p></li></ol><h2 id="_3-14-9-technical-support-and-product-discussion" tabindex="-1">3.14.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-14-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.14.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+y+'" class="common_img" style="width:800px;aspect-ratio:1136 / 640;"></a>',38))])}const Q=v(q,[["render",D]]);export{M as __pageData,Q as default};
